    {
      "card_ids": ["C06"],
      "claim": "The closest analogue, an aniline-amide with an aryl fluoride, achieved a brain:plasma ratio of 1.29 in mice after IP dosing, directly demonstrating that this amide/aniline phenotype can confer good CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "An oxazolidinone analogue with an aniline fluoride and amide showed a brain/plasma AUC ratio of 2.65 after oral dosing in mice, supporting CNS access for a similarly sized, amide-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A fused pyrazolopyridinone benzamide had brain/plasma <0.08 in rats, showing that some fused pyrazole-amide scaffolds can be efflux-limited; this is a cautionary contradictory signal, though the query lacks the lactam and secondary benzamide.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "A polar amide/ether-containing compound was labeled permeable in a mouse neuroPK study with an unbound brain/plasma ratio of 0.2, indicating measurable CNS access despite polar functionality.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted pass: the query is a neutral, moderately lipophilic, CNS-drug-like molecule (MW 399, logD 3.38, HBD 2) and the preponderance of direct brain-penetration evidence from structurally related amide/heteroaryl compounds supports meaningful CNS access. Two low-exposure pyrazolopyridinone analogues are a caution, but the query's smaller size, neutral weak base, and lack of lactam/benzamide reduce that transfer; overall confidence is low due to weak analogue similarity.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or unbound brain exposure measurement for the query itself.",
    "All experimental analogues have low Morgan similarity (<0.25), limiting structural transfer.",
    "Primary amide and THF-amine efflux liability not experimentally characterized.",
    "No human or non-human primate PK data for the exact query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

